import re
import unicodedata
import difflib
from jiwer import wer, cer
import Levenshtein
from fugashi import Tagger


# ----------------------------
# 1. Normalization Function
# ----------------------------
def normalize_text(text):
    # Convert full-width to half-width and normalize unicode
    text = unicodedata.normalize("NFKC", text)

    # Remove punctuation
    text = re.sub(r"[。、！？,.!?]", "", text)

    # Remove extra spaces
    text = re.sub(r"\s+", "", text)

    return text


# ----------------------------
# 2. Tokenization (Japanese)
# ----------------------------
def tokenize_japanese(text):
    tagger = Tagger()
    words = [word.surface for word in tagger(text)]
    return words


# ----------------------------
# 3. Evaluation Function
# ----------------------------
def evaluate(reference_raw, hypothesis_raw):

    # Normalize
    reference = normalize_text(reference_raw)
    hypothesis = normalize_text(hypothesis_raw)

    print("===== Basic Info =====")
    print("Reference Length:", len(reference))
    print("Hypothesis Length:", len(hypothesis))
    print()

    # ------------------------
    # Character Error Rate
    # ------------------------
    char_error_rate = cer(reference, hypothesis)
    print("Character Error Rate (CER):", round(char_error_rate, 4))

    # ------------------------
    # Word Error Rate
    # ------------------------
    ref_tokens = tokenize_japanese(reference)
    hyp_tokens = tokenize_japanese(hypothesis)

    ref_str = " ".join(ref_tokens)
    hyp_str = " ".join(hyp_tokens)

    word_error_rate = wer(ref_str, hyp_str)
    print("Word Error Rate (WER):", round(word_error_rate, 4))

    # ------------------------
    # Levenshtein Distance
    # ------------------------
    lev_distance = Levenshtein.distance(reference, hypothesis)
    print("Levenshtein Distance:", lev_distance)

    # Normalized similarity score
    similarity = Levenshtein.ratio(reference, hypothesis)
    print("Similarity Score:", round(similarity, 4))

    # ------------------------
    # Precision / Recall / F1
    # ------------------------
    ref_set = set(ref_tokens)
    hyp_set = set(hyp_tokens)

    true_positive = len(ref_set.intersection(hyp_set))
    precision = true_positive / len(hyp_set) if hyp_set else 0
    recall = true_positive / len(ref_set) if ref_set else 0
    f1 = 2 * precision * recall / (precision + recall) if (precision + recall) else 0

    print("\n===== Token Level Metrics =====")
    print("Precision:", round(precision, 4))
    print("Recall:", round(recall, 4))
    print("F1 Score:", round(f1, 4))

    # ------------------------
    # Detailed Diff
    # ------------------------
    # print("\n===== Detailed Character Differences =====")
    # diff = difflib.ndiff(reference, hypothesis)
